23| \begin{tikzpicture}[scale=0.55]
24|   \foreach \g in {0,1,2,3} {
25|     \draw[omExo, rounded corners] (\g*4.9-0.65,-0.7) rectangle
26|       (\g*4.9+3.85,0.7);
27|     \foreach \c in {0,...,4} \fill[omDef] (\g*4.9+\c*0.8,0) circle (0.27);
28|   }
29|=
30|     {$20$ 颗弹珠，分成 $4$ 个相等的组：每组 $5$ 颗};
31| \end{tikzpicture}
32|=
33| {\small 将 $20$ 平均分成 $4$ 组。若改为每 $4$ 个一组，
34| 则得到 $5$ 组 --- 是同一个除法。}
35| \end{omfigure}
